// One message: the market in a line, then each of your stocks.
const pulse = $('Market Pulse').first().json;
const stocks = $('My Stocks').all().map(i => i.json);

const fg = pulse.fear_greed || {};
const spy = (pulse.indices || {}).spy || {};
const pct = (n) => (n === null || n === undefined) ? 'n/a' : `${n > 0 ? '+' : ''}${n}%`;

const lines = [
  `*Stocklake briefing, ${new Date().toDateString()}*`,
  `S&P 500 (SPY) ${pct(spy.change_pct)} | VIX ${pulse.vix ?? 'n/a'} | Fear & Greed ${fg.value ?? 'n/a'} (${fg.description ?? 'n/a'})`,
  '',
];
for (const s of stocks) {
  if (s.error) { lines.push(`${s.symbol}: ${s.error}`); continue; }
  const note = s.rsi >= 70 ? ' (overbought)' : s.rsi <= 30 ? ' (oversold)' : '';
  lines.push(`*${s.symbol}* ${s.price} ${pct(s.change_pct)} | RSI ${s.rsi ?? 'n/a'}${note} | analysts: ${(s.analyst_rating || 'n/a').replace('_', ' ')}`);
}
return [{ json: { text: lines.join('\n') } }];
